shares\":\"0\",\"vaultAssets\":\"0\",\"reserves\":{\"A\":\"10000000000\",\"B\":\"10000000000\"},\"nonce\":1,\"formatted\":{\"unit\":\"token\",\"tokenDecimals\":6,\"nativeDecimals\":18,\"balances\":{\"agentA\":\"100\",\"agentB\":\"0\",\"recipientA\":\"0\",\"recipientB\":\"0\",\"native\":\"9.999939750639472135\"},\"allowances\":{\"ammA\":\"20\",\"vaultB\":\"0\"},\"reserves\":{\"A\":\"10000\",\"B\":\"10000\"},\"shares\":\"0\",\"vaultAssets\":\"0\"}},\"scope\":\"本次目标相对本次initialState判定。兑换后存入仅存本次兑换新增的TokenB，保留本次运行前已有的TokenB及份额。\"}"
